    make(8, "下列哪個敘述指出『溶解』本身不等於已完成分離？", {"A": "食鹽消失在水中只是形成溶液，仍需蒸發或蒸餾才能回收成分", "B": "食鹽溶解後就變成另一種元素", "C": "溶解會使水和食鹽無法再分開", "D": "溶解必定是化學反應"}, "A", "食鹽溶解是形成均勻混合物的物理過程，仍可用蒸發結晶或蒸餾分離，選 A。", "區分『成分暫時分散』和『成分真正被取出』兩個階段。", ["觀察食鹽進入水中形成均勻溶液。", "沒有新物質生成，成分仍存在。", "溶解只改變分散狀態。", "需再利用揮發性或溶解度差異回收。", "所以選 A。"], "easy"),
    make(9, "蒸發結晶得到的白色固體若仍含少量雜質，最適合的改進方向是？", {"A": "控制溶解、過濾與結晶條件，必要時再結晶並檢查回收物", "B": "直接宣稱白色就代表百分之百純", "C": "加入更多未知物掩蓋顏色", "D": "把晶體和濾紙一起稱作純品"}, "A", "顏色不能證明純度；可利用溶解度差異進行再結晶、過濾並以質量或成分檢查驗證，選 A。", "把分離結果和純度驗證分開，最後再找造成污染或損失的步驟。", ["白色外觀只能提供初步線索。", "檢查濾紙、濾液與晶體是否交叉污染。", "依溶解度差異安排再結晶。", "乾燥後再量質量或用檢測方法驗證。", "所以改進方向選 A。"], "hard"),
    make(10, "若混合物成分的沸點非常接近，直接蒸餾可能分離效果不佳。最合理的說法是？", {"A": "性質差異太小，應改進分餾或選擇其他可利用的性質差異", "B": "蒸餾一定能得到兩種百分之百純物質", "C": "沸點接近表示它們必定是同一物質", "D": "只要加大火力就能改變成分的沸點"}, "A", "沸點接近會使蒸氣組成差異小，簡單蒸餾難以有效分離；可考慮分餾或其他方法，選 A。", "先評估性質差異是否足夠，再決定是否需要更精細的程序。", ["比較兩成分的沸點差距。", "差距小代表一次汽化冷凝的選擇性有限。", "分餾可增加多次平衡接觸以改善分離。", "也可尋找溶解度或吸附性等其他差異。", "所以選 A。"], "hard"),
